def transform(grid):
    """Downsample 3x3 cells to the color other than the two backgrounds."""
    output = []
    for top in range(0, len(grid), 3):
        row = []
        for left in range(0, len(grid[0]), 3):
            colors = Counter(
                grid[r][c]
                for r in range(top, min(top + 3, len(grid)))
                for c in range(left, min(left + 3, len(grid[0])))
                if grid[r][c] not in (0, 5)
            )
            row.append(colors.most_common(1)[0][0] if colors else 0)
        output.append(row)
    return output


